-- Koda mobile: apply once to the SAME Supabase database used by the web.
-- Generated by npm run server:sql. Does not include the reference schema.
-- Requires the existing Koda tables. Every change is in one transaction.
BEGIN;

-- 001_existing_thermal_alerts.sql
-- =============================================================
-- MIGRATION 003 — Alertas automáticos de temperatura por carga
-- =============================================================
-- Cria:
--   1. Tabela `carga_alertas` (1 linha por evento térmico contínuo)
--   2. Função `fn_carga_telemetria_processar_alertas`
--   3. Trigger AFTER INSERT em `carga_telemetria_auditoria` que
--      abre/atualiza/fecha alertas conforme as leituras chegam
--
-- Modelo de evento:
--   • Cada vez que a temperatura sai da faixa (`temperatura_minima` /
--     `temperatura_maxima` da `carga`) o trigger ABRE um alerta com
--     status='aberto'.
--   • Enquanto a temperatura continua fora da faixa (do mesmo lado),
--     novos pings só ATUALIZAM o pico e incrementam qtd_pings — não
--     geram alertas novos (evita spam).
--   • Quando a temperatura volta para dentro da faixa, ou cruza para o
--     lado oposto, o alerta aberto é FECHADO (status='resolvido').
--   • Garantia de unicidade: índice parcial impede 2 alertas abertos
--     simultaneamente para a mesma (carga, tipo).
--
-- Idempotente: pode rodar várias vezes.
-- Executar no Supabase SQL Editor ou via psql.
-- =============================================================


-- -------------------------------------------------------------
-- 1) Tabela de alertas
-- -------------------------------------------------------------
CREATE TABLE IF NOT EXISTS carga_alertas (
    id                          SERIAL PRIMARY KEY,
    id_carga                    INT             NOT NULL,

    -- 'alta' = temperatura > limite_maximo
    -- 'baixa' = temperatura < limite_minimo
    tipo                        VARCHAR(10)     NOT NULL,

    -- 'aberto' | 'resolvido' | 'cancelado' (cancelado = encerrado manualmente)
    status                      VARCHAR(20)     NOT NULL DEFAULT 'aberto',

    -- Snapshot da faixa no momento da abertura: se a operadora alterar
    -- depois a faixa-referência da carga, o alerta histórico continua
    -- mostrando contra quais limites ele foi disparado.
    limite_minimo               DECIMAL(5,2)    NOT NULL,
    limite_maximo               DECIMAL(5,2)    NOT NULL,

    -- Temperaturas envolvidas no evento
    temperatura_inicio          DECIMAL(5,2)    NOT NULL,
    -- pico = máx p/ tipo 'alta'; mín p/ tipo 'baixa'
    temperatura_pico            DECIMAL(5,2)    NOT NULL,
    -- temperatura do ping que resolveu o alerta (NULL enquanto aberto)
    temperatura_fim             DECIMAL(5,2),

    -- Estatísticas / referências
    qtd_pings                   INT             NOT NULL DEFAULT 1,
    aberto_telemetria_id        INT,
    resolvido_telemetria_id     INT,

    -- Timestamps
    aberto_at                   TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    resolvido_at                TIMESTAMP,
    created_at                  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at                  TIMESTAMP       NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_carga_alertas_carga
        FOREIGN KEY (id_carga) REFERENCES carga(id) ON DELETE CASCADE,

    -- Se um ping for removido por retenção, o alerta sobrevive (SET NULL)
    CONSTRAINT fk_carga_alertas_telem_aberto
        FOREIGN KEY (aberto_telemetria_id)
        REFERENCES carga_telemetria_auditoria(id) ON DELETE SET NULL,

    CONSTRAINT fk_carga_alertas_telem_resolvido
        FOREIGN KEY (resolvido_telemetria_id)
        REFERENCES carga_telemetria_auditoria(id) ON DELETE SET NULL,

    CONSTRAINT chk_carga_alertas_tipo   CHECK (tipo   IN ('alta','baixa')),
    CONSTRAINT chk_carga_alertas_status CHECK (status IN ('aberto','resolvido','cancelado'))
);

-- Buscas frequentes
CREATE INDEX IF NOT EXISTS idx_carga_alertas_carga   ON carga_alertas (id_carga);
CREATE INDEX IF NOT EXISTS idx_carga_alertas_status  ON carga_alertas (status);
CREATE INDEX IF NOT EXISTS idx_carga_alertas_aberto_at
    ON carga_alertas (aberto_at DESC);

-- Garante "no máximo 1 alerta ABERTO por (carga, tipo)" — base da lógica anti-spam
CREATE UNIQUE INDEX IF NOT EXISTS uq_carga_alertas_um_aberto_por_tipo
    ON carga_alertas (id_carga, tipo)
    WHERE status = 'aberto';

COMMENT ON TABLE  carga_alertas IS
    'Eventos contínuos de violação térmica por carga (1 linha = 1 evento, do momento que saiu da faixa até voltar/cruzar).';
COMMENT ON COLUMN carga_alertas.tipo IS
    'alta = temperatura excedeu temperatura_maxima; baixa = temperatura ficou abaixo de temperatura_minima.';
COMMENT ON COLUMN carga_alertas.temperatura_pico IS
    'Pior leitura registrada durante o evento (máx p/ tipo alta, mín p/ tipo baixa).';


-- -------------------------------------------------------------
-- 2) Função do trigger
-- -------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_carga_telemetria_processar_alertas()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_min       DECIMAL(5,2);
    v_max       DECIMAL(5,2);
    v_tipo      TEXT;
    v_alerta_id INT;
BEGIN
    -- Lê faixa atual da carga referenciada
    SELECT temperatura_minima, temperatura_maxima
      INTO v_min, v_max
      FROM carga
     WHERE id = NEW.id_carga;

    -- Se a carga não existe ou não tem faixa, não há o que avaliar
    IF v_min IS NULL OR v_max IS NULL THEN
        RETURN NEW;
    END IF;

    -- Classifica a leitura
    IF NEW.temperatura > v_max THEN
        v_tipo := 'alta';
    ELSIF NEW.temperatura < v_min THEN
        v_tipo := 'baixa';
    ELSE
        v_tipo := NULL;  -- dentro da faixa
    END IF;

    ----------------------------------------------------------------
    -- CASO A: leitura DENTRO da faixa
    --   Fecha qualquer alerta aberto da carga (independente do tipo).
    ----------------------------------------------------------------
    IF v_tipo IS NULL THEN
        UPDATE carga_alertas
           SET status                  = 'resolvido',
               resolvido_at            = NEW.created_at,
               resolvido_telemetria_id = NEW.id,
               temperatura_fim         = NEW.temperatura,
               qtd_pings               = qtd_pings + 1,
               updated_at              = CURRENT_TIMESTAMP
         WHERE id_carga = NEW.id_carga
           AND status   = 'aberto';

        RETURN NEW;
    END IF;

    ----------------------------------------------------------------
    -- CASO B: leitura FORA da faixa
    --   B.1) Existe alerta aberto do MESMO tipo  → só atualiza
    --   B.2) Existe alerta aberto do TIPO OPOSTO → fecha o oposto e
    --        abre o novo (cruzou de baixa para alta ou vice-versa)
    --   B.3) Não existe alerta aberto            → abre novo
    --
    -- Lock pessimista (FOR UPDATE) garante que dois inserts
    -- concorrentes não criem 2 alertas iguais (o índice unique parcial
    -- também blinda isso, mas o lock evita o erro 23505).
    ----------------------------------------------------------------
    SELECT id INTO v_alerta_id
      FROM carga_alertas
     WHERE id_carga = NEW.id_carga
       AND tipo     = v_tipo
       AND status   = 'aberto'
     FOR UPDATE;

    IF FOUND THEN
        -- B.1 — só atualiza pico e contagem
        UPDATE carga_alertas
           SET temperatura_pico = CASE
                   WHEN tipo = 'alta' THEN GREATEST(temperatura_pico, NEW.temperatura)
                   ELSE                   LEAST   (temperatura_pico, NEW.temperatura)
               END,
               qtd_pings  = qtd_pings + 1,
               updated_at = CURRENT_TIMESTAMP
         WHERE id = v_alerta_id;
    ELSE
        -- B.2 — fecha alerta do tipo OPOSTO se houver
        UPDATE carga_alertas
           SET status                  = 'resolvido',
               resolvido_at            = NEW.created_at,
               resolvido_telemetria_id = NEW.id,
               temperatura_fim         = NEW.temperatura,
               qtd_pings               = qtd_pings + 1,
               updated_at              = CURRENT_TIMESTAMP
         WHERE id_carga = NEW.id_carga
           AND tipo    <> v_tipo
           AND status   = 'aberto';

        -- B.3 — abre novo
        INSERT INTO carga_alertas (
            id_carga, tipo, status,
            limite_minimo, limite_maximo,
            temperatura_inicio, temperatura_pico,
            aberto_telemetria_id,
            aberto_at, qtd_pings
        ) VALUES (
            NEW.id_carga, v_tipo, 'aberto',
            v_min, v_max,
            NEW.temperatura, NEW.temperatura,
            NEW.id,
            NEW.created_at, 1
        );
    END IF;

    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION fn_carga_telemetria_processar_alertas() IS
    'Abre/atualiza/fecha registros em carga_alertas conforme cada novo ping em carga_telemetria_auditoria.';


-- -------------------------------------------------------------
-- 3) Trigger
-- -------------------------------------------------------------
DROP TRIGGER IF EXISTS trg_carga_telemetria_alertas
    ON carga_telemetria_auditoria;

CREATE TRIGGER trg_carga_telemetria_alertas
AFTER INSERT ON carga_telemetria_auditoria
FOR EACH ROW
EXECUTE FUNCTION fn_carga_telemetria_processar_alertas();


-- -------------------------------------------------------------
-- 4) Manutenção de `updated_at`
-- -------------------------------------------------------------
CREATE OR REPLACE FUNCTION fn_carga_alertas_set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_carga_alertas_updated_at ON carga_alertas;

CREATE TRIGGER trg_carga_alertas_updated_at
BEFORE UPDATE ON carga_alertas
FOR EACH ROW
EXECUTE FUNCTION fn_carga_alertas_set_updated_at();


-- -------------------------------------------------------------
-- 5) (Opcional / Supabase) — políticas RLS
-- -------------------------------------------------------------
-- Em Supabase, lembre-se de habilitar RLS e definir policies coerentes
-- com a forma como o app web/admin lê esses dados:
--
--   ALTER TABLE carga_alertas ENABLE ROW LEVEL SECURITY;
--
--   CREATE POLICY carga_alertas_read_authenticated
--     ON carga_alertas
--     FOR SELECT
--     TO authenticated
--     USING (true);
--
--   -- Inserts/updates só devem vir da própria trigger (SECURITY DEFINER
--   -- não é necessário porque o trigger roda com privilégios do owner
--   -- da função). Bloqueia escrita direta da anon key:
--   CREATE POLICY carga_alertas_no_direct_write
--     ON carga_alertas
--     FOR INSERT, UPDATE, DELETE
--     TO anon
--     USING (false)
--     WITH CHECK (false);



-- 002_mobile_operations.sql
-- Apply once to the SAME database used by koda-web / koda-server.
-- Existing schema.sql + migration 003_carga_alertas.sql are prerequisites.

ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS motorista_id_mobile integer REFERENCES public.users(id);
ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS carga_id_mobile integer REFERENCES public.carga(id);
ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS sensor_id_mobile text;
ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS snapshot_mobile jsonb;
ALTER TABLE public.carga_telemetria_auditoria ADD COLUMN IF NOT EXISTS id_entrega_mobile integer REFERENCES public.entregas(id);
ALTER TABLE public.carga_telemetria_auditoria ADD COLUMN IF NOT EXISTS client_id_mobile uuid;
CREATE UNIQUE INDEX IF NOT EXISTS uq_mobile_reading_client ON public.carga_telemetria_auditoria(client_id_mobile);
CREATE INDEX IF NOT EXISTS idx_mobile_trip_readings ON public.carga_telemetria_auditoria(id_entrega_mobile, created_at);

-- Every RPC is invoker-rights and executable ONLY by the server role.
-- p_driver comes from /users/profile, never from a client-provided driver ID.
CREATE OR REPLACE FUNCTION public.koda_mobile_trips(p_driver integer, p_trip integer DEFAULT NULL)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$
 SELECT coalesce(jsonb_agg(row ORDER BY (row->>'id')::integer DESC), '[]'::jsonb) FROM (
 SELECT to_jsonb(e) || jsonb_build_object(
   'caminhao', coalesce(e.snapshot_mobile->'caminhao', to_jsonb(t)),
   'carga', coalesce(e.snapshot_mobile->'carga', to_jsonb(c)) || jsonb_build_object('temperatura_atual', c.temperatura_atual, 'latitude', c.latitude, 'longitude', c.longitude),
   'cliente', coalesce(e.snapshot_mobile->'cliente', to_jsonb(cl)),
   'centro', coalesce(e.snapshot_mobile->'centro', to_jsonb(ce))
 ) AS row
 FROM public.entregas e JOIN public.caminhao t ON t.id = e.id_caminhao
 LEFT JOIN public.carga c ON c.id = coalesce(e.carga_id_mobile, t.id_carga)
 JOIN public.clientes cl ON cl.id = e.id_cliente
 LEFT JOIN public.centro_logistica ce ON ce.id = t.id_centro_logistica
 WHERE coalesce(e.motorista_id_mobile, t.id_usuario) = p_driver
 AND (p_trip IS NULL OR e.id = p_trip)
 AND EXISTS (SELECT 1 FROM public.users u WHERE u.id = p_driver AND u.role = 'driver' AND u.is_active)
 ) x;
$$;

CREATE OR REPLACE FUNCTION public.koda_mobile_start(p_driver integer, p_trip integer, p_sensor text DEFAULT NULL, p_position jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE e public.entregas; t public.caminhao; c public.carga; cl public.clientes; ce public.centro_logistica;
BEGIN
 PERFORM 1 FROM users WHERE id=p_driver AND role='driver' AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Motorista sem acesso' USING ERRCODE='42501'; END IF;
 -- Lock the vehicle before the trip consistently across start/finish/telemetry.
 SELECT t0.* INTO t FROM caminhao t0 JOIN entregas e0 ON e0.id_caminhao=t0.id WHERE e0.id=p_trip FOR UPDATE OF t0;
 SELECT * INTO e FROM entregas WHERE id=p_trip FOR UPDATE;
 IF e.id IS NULL OR coalesce(e.motorista_id_mobile,t.id_usuario) <> p_driver THEN RAISE EXCEPTION 'Viagem indisponível' USING ERRCODE='42501'; END IF;
 IF e.status IN ('em_transito','no_armazem') THEN RETURN jsonb_build_object('id', e.id, 'status', e.status); END IF;
 IF e.status <> 'pendente' OR t.status NOT IN ('disponivel','em_espera') THEN RAISE EXCEPTION 'Viagem ou veículo não disponível para início' USING ERRCODE='P0001'; END IF;
 IF EXISTS (SELECT 1 FROM entregas e2 JOIN caminhao t2 ON t2.id=e2.id_caminhao WHERE e2.id<>e.id AND e2.status IN ('em_transito','no_armazem') AND (e2.id_caminhao=t.id OR coalesce(e2.motorista_id_mobile,t2.id_usuario)=p_driver)) THEN RAISE EXCEPTION 'Conclua a viagem ativa antes de iniciar outra' USING ERRCODE='P0001'; END IF;
 SELECT * INTO c FROM carga WHERE id=t.id_carga FOR UPDATE;
 SELECT * INTO cl FROM clientes WHERE id=e.id_cliente;
 SELECT * INTO ce FROM centro_logistica WHERE id=t.id_centro_logistica;
 IF c.id IS NULL OR c.temperatura_minima > c.temperatura_maxima OR NOT cl.is_ativo THEN RAISE EXCEPTION 'Revise a carga e o destinatário com a central' USING ERRCODE='P0001'; END IF;
 IF p_position IS NOT NULL AND ((p_position->>'latitude')::numeric NOT BETWEEN -90 AND 90 OR (p_position->>'longitude')::numeric NOT BETWEEN -180 AND 180) THEN RAISE EXCEPTION 'Posição inválida' USING ERRCODE='22023'; END IF;
 UPDATE entregas SET status='em_transito', data_saida=timezone('utc',now()), updated_at=timezone('utc',now()), motorista_id_mobile=p_driver, carga_id_mobile=c.id, sensor_id_mobile=p_sensor,
 snapshot_mobile=jsonb_build_object('caminhao',to_jsonb(t),'carga',to_jsonb(c),'cliente',to_jsonb(cl),'centro',to_jsonb(ce),'start_position',p_position) WHERE id=p_trip;
 IF p_position IS NOT NULL THEN UPDATE carga SET latitude=coalesce((p_position->>'latitude')::numeric,latitude),longitude=coalesce((p_position->>'longitude')::numeric,longitude),updated_at=timezone('utc',now()) WHERE id=c.id; END IF;
 UPDATE caminhao SET status='em_rota', updated_at=timezone('utc',now()) WHERE id=t.id;
 RETURN jsonb_build_object('id',p_trip,'status','em_transito');
END;
$$;

CREATE OR REPLACE FUNCTION public.koda_mobile_sensor(p_driver integer, p_trip integer, p_sensor text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE e public.entregas;
BEGIN
 SELECT e0.* INTO e FROM entregas e0 JOIN caminhao t ON t.id=e0.id_caminhao
 WHERE e0.id=p_trip AND coalesce(e0.motorista_id_mobile,t.id_usuario)=p_driver FOR UPDATE OF e0;
 IF e.id IS NULL OR NOT EXISTS (SELECT 1 FROM users WHERE id=p_driver AND role='driver' AND is_active) THEN RAISE EXCEPTION 'Viagem indisponível' USING ERRCODE='42501'; END IF;
 IF e.status NOT IN ('pendente','em_transito','no_armazem') THEN RAISE EXCEPTION 'Viagem encerrada' USING ERRCODE='P0001'; END IF;
 IF length(p_sensor) NOT BETWEEN 1 AND 128 THEN RAISE EXCEPTION 'Sensor inválido' USING ERRCODE='22023'; END IF;
 UPDATE entregas SET sensor_id_mobile=p_sensor,updated_at=timezone('utc',now()) WHERE id=e.id;
END;
$$;

CREATE OR REPLACE FUNCTION public.koda_mobile_telemetry(p_driver integer, p_readings jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE r jsonb; e public.entregas; t public.caminhao; cargo_id integer; accepted jsonb := '[]'; stamp timestamp; existing public.carga_telemetria_auditoria;
BEGIN
 PERFORM 1 FROM users WHERE id=p_driver AND role='driver' AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Motorista sem acesso' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_readings)<>'array' OR jsonb_array_length(p_readings) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Lote inválido' USING ERRCODE='22023'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_readings) ORDER BY (value->>'tripId')::integer,(value->>'timestamp')::timestamptz LOOP
   SELECT t0.* INTO t FROM caminhao t0 JOIN entregas e0 ON e0.id_caminhao=t0.id WHERE e0.id=(r->>'tripId')::integer FOR UPDATE OF t0;
   SELECT * INTO e FROM entregas WHERE id=(r->>'tripId')::integer FOR UPDATE;
   IF e.id IS NULL OR coalesce(e.motorista_id_mobile,t.id_usuario)<>p_driver THEN RAISE EXCEPTION 'Viagem indisponível' USING ERRCODE='42501'; END IF;
   SELECT * INTO existing FROM carga_telemetria_auditoria WHERE client_id_mobile=(r->>'id')::uuid;
   IF existing.id IS NOT NULL THEN
     IF existing.id_entrega_mobile IS DISTINCT FROM e.id
       OR existing.temperatura IS DISTINCT FROM round((r->>'temperature')::numeric,2)
       OR existing.created_at IS DISTINCT FROM timezone('utc',(r->>'timestamp')::timestamptz)
       OR existing.latitude IS DISTINCT FROM round((r->>'latitude')::numeric,6)
       OR existing.longitude IS DISTINCT FROM round((r->>'longitude')::numeric,6) THEN RAISE EXCEPTION 'Identificador reutilizado com dados diferentes' USING ERRCODE='22023'; END IF;
     accepted:=accepted || jsonb_build_array(r->>'id'); CONTINUE;
   END IF;
   IF e.status NOT IN ('em_transito','no_armazem') THEN RAISE EXCEPTION 'Viagem não está ativa' USING ERRCODE='P0001'; END IF;
   cargo_id:=coalesce(e.carga_id_mobile,t.id_carga);
   IF cargo_id IS NULL THEN RAISE EXCEPTION 'Carga não informada' USING ERRCODE='P0001'; END IF;
   PERFORM 1 FROM carga WHERE id=cargo_id FOR UPDATE;
   stamp:=timezone('utc',(r->>'timestamp')::timestamptz);
   IF stamp IS NULL OR stamp > timezone('utc',now())+interval '1 minute' OR stamp < e.data_saida-interval '1 minute'
      OR (r->>'temperature') IS NULL OR (r->>'temperature')::numeric NOT BETWEEN -100 AND 100
      OR ((r->>'latitude') IS NOT NULL AND (r->>'latitude')::numeric NOT BETWEEN -90 AND 90)
      OR ((r->>'longitude') IS NOT NULL AND (r->>'longitude')::numeric NOT BETWEEN -180 AND 180)
   THEN RAISE EXCEPTION 'Leitura inválida' USING ERRCODE='22023'; END IF;
   INSERT INTO carga_telemetria_auditoria(id_carga,id_entrega_mobile,client_id_mobile,temperatura,latitude,longitude,created_at)
   VALUES(cargo_id,e.id,(r->>'id')::uuid,(r->>'temperature')::numeric,(r->>'latitude')::numeric,(r->>'longitude')::numeric,stamp);
   -- Preserve the latest known temperature/GPS when an older offline packet arrives.
   IF NOT EXISTS(SELECT 1 FROM carga_telemetria_auditoria WHERE id_carga=cargo_id AND created_at>stamp) THEN
     UPDATE carga SET temperatura_atual=(r->>'temperature')::numeric,latitude=coalesce((r->>'latitude')::numeric,latitude),longitude=coalesce((r->>'longitude')::numeric,longitude),updated_at=timezone('utc',now()) WHERE id=cargo_id;
   END IF;
   accepted:=accepted || jsonb_build_array(r->>'id');
 END LOOP;
 RETURN jsonb_build_object('acceptedIds',accepted);
END;
$$;

CREATE OR REPLACE FUNCTION public.koda_mobile_finish(p_driver integer, p_trip integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE e public.entregas; t public.caminhao; c public.carga; cl public.clientes; ce public.centro_logistica;
BEGIN
 PERFORM 1 FROM users WHERE id=p_driver AND role='driver' AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Motorista sem acesso' USING ERRCODE='42501'; END IF;
 SELECT t0.* INTO t FROM caminhao t0 JOIN entregas e0 ON e0.id_caminhao=t0.id WHERE e0.id=p_trip FOR UPDATE OF t0;
 SELECT * INTO e FROM entregas WHERE id=p_trip FOR UPDATE;
 IF e.id IS NULL OR coalesce(e.motorista_id_mobile,t.id_usuario)<>p_driver THEN RAISE EXCEPTION 'Viagem indisponível' USING ERRCODE='42501'; END IF;
 IF e.status='entregue' THEN RETURN jsonb_build_object('id',e.id,'status',e.status); END IF;
 IF e.status NOT IN ('em_transito','no_armazem') THEN RAISE EXCEPTION 'Apenas uma viagem ativa pode ser concluída' USING ERRCODE='P0001'; END IF;
 SELECT * INTO c FROM carga WHERE id=coalesce(e.carga_id_mobile,t.id_carga);
 SELECT * INTO cl FROM clientes WHERE id=e.id_cliente;
 SELECT * INTO ce FROM centro_logistica WHERE id=t.id_centro_logistica;
 UPDATE entregas SET snapshot_mobile=coalesce(e.snapshot_mobile,jsonb_build_object('caminhao',to_jsonb(t),'carga',to_jsonb(c),'cliente',to_jsonb(cl),'centro',to_jsonb(ce))),status='entregue',data_entrega=timezone('utc',now()),updated_at=timezone('utc',now()),motorista_id_mobile=p_driver,carga_id_mobile=coalesce(e.carga_id_mobile,t.id_carga) WHERE id=e.id;
 IF NOT EXISTS(SELECT 1 FROM entregas WHERE id_caminhao=t.id AND id<>e.id AND status IN ('em_transito','no_armazem')) THEN UPDATE caminhao SET status='disponivel',updated_at=timezone('utc',now()) WHERE id=t.id; END IF;
 RETURN jsonb_build_object('id',e.id,'status','entregue');
END;
$$;

REVOKE ALL ON FUNCTION public.koda_mobile_trips(integer,integer), public.koda_mobile_start(integer,integer,text,jsonb), public.koda_mobile_sensor(integer,integer,text), public.koda_mobile_telemetry(integer,jsonb), public.koda_mobile_finish(integer,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.koda_mobile_trips(integer,integer), public.koda_mobile_start(integer,integer,text,jsonb), public.koda_mobile_sensor(integer,integer,text), public.koda_mobile_telemetry(integer,jsonb), public.koda_mobile_finish(integer,integer) TO service_role;


-- 003_offline_alert_order.sql
-- Keep the existing central alert trigger chronological. Run after 001 and 002.

CREATE OR REPLACE FUNCTION fn_carga_telemetria_processar_alertas()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_min       DECIMAL(5,2);
    v_max       DECIMAL(5,2);
    v_tipo      TEXT;
    v_alerta_id INT;
BEGIN
    -- Offline packets remain in the audit trail. They must not reverse a newer
    -- thermal state already observed by the web central or another device.
    IF EXISTS (SELECT 1 FROM public.carga_telemetria_auditoria
        WHERE id_carga = NEW.id_carga AND
        (created_at > NEW.created_at OR (created_at = NEW.created_at AND id > NEW.id))) THEN
        RETURN NEW;
    END IF;
    -- Lê faixa atual da carga referenciada
    SELECT temperatura_minima, temperatura_maxima
      INTO v_min, v_max
      FROM carga
     WHERE id = NEW.id_carga;

    -- Se a carga não existe ou não tem faixa, não há o que avaliar
    IF v_min IS NULL OR v_max IS NULL THEN
        RETURN NEW;
    END IF;

    -- Classifica a leitura
    IF NEW.temperatura > v_max THEN
        v_tipo := 'alta';
    ELSIF NEW.temperatura < v_min THEN
        v_tipo := 'baixa';
    ELSE
        v_tipo := NULL;  -- dentro da faixa
    END IF;

    ----------------------------------------------------------------
    -- CASO A: leitura DENTRO da faixa
    --   Fecha qualquer alerta aberto da carga (independente do tipo).
    ----------------------------------------------------------------
    IF v_tipo IS NULL THEN
        UPDATE carga_alertas
           SET status                  = 'resolvido',
               resolvido_at            = NEW.created_at,
               resolvido_telemetria_id = NEW.id,
               temperatura_fim         = NEW.temperatura,
               qtd_pings               = qtd_pings + 1,
               updated_at              = CURRENT_TIMESTAMP
         WHERE id_carga = NEW.id_carga
           AND status   = 'aberto';

        RETURN NEW;
    END IF;

    ----------------------------------------------------------------
    -- CASO B: leitura FORA da faixa
    --   B.1) Existe alerta aberto do MESMO tipo  → só atualiza
    --   B.2) Existe alerta aberto do TIPO OPOSTO → fecha o oposto e
    --        abre o novo (cruzou de baixa para alta ou vice-versa)
    --   B.3) Não existe alerta aberto            → abre novo
    --
    -- Lock pessimista (FOR UPDATE) garante que dois inserts
    -- concorrentes não criem 2 alertas iguais (o índice unique parcial
    -- também blinda isso, mas o lock evita o erro 23505).
    ----------------------------------------------------------------
    SELECT id INTO v_alerta_id
      FROM carga_alertas
     WHERE id_carga = NEW.id_carga
       AND tipo     = v_tipo
       AND status   = 'aberto'
     FOR UPDATE;

    IF FOUND THEN
        -- B.1 — só atualiza pico e contagem
        UPDATE carga_alertas
           SET temperatura_pico = CASE
                   WHEN tipo = 'alta' THEN GREATEST(temperatura_pico, NEW.temperatura)
                   ELSE                   LEAST   (temperatura_pico, NEW.temperatura)
               END,
               qtd_pings  = qtd_pings + 1,
               updated_at = CURRENT_TIMESTAMP
         WHERE id = v_alerta_id;
    ELSE
        -- B.2 — fecha alerta do tipo OPOSTO se houver
        UPDATE carga_alertas
           SET status                  = 'resolvido',
               resolvido_at            = NEW.created_at,
               resolvido_telemetria_id = NEW.id,
               temperatura_fim         = NEW.temperatura,
               qtd_pings               = qtd_pings + 1,
               updated_at              = CURRENT_TIMESTAMP
         WHERE id_carga = NEW.id_carga
           AND tipo    <> v_tipo
           AND status   = 'aberto';

        -- B.3 — abre novo
        INSERT INTO carga_alertas (
            id_carga, tipo, status,
            limite_minimo, limite_maximo,
            temperatura_inicio, temperatura_pico,
            aberto_telemetria_id,
            aberto_at, qtd_pings
        ) VALUES (
            NEW.id_carga, v_tipo, 'aberto',
            v_min, v_max,
            NEW.temperatura, NEW.temperatura,
            NEW.id,
            NEW.created_at, 1
        );
    END IF;

    RETURN NEW;
END;
$$;




-- 004_operational_reliability.sql
-- Upgrade for existing installations: overlapping alerts and offline reconciliation.

CREATE TABLE IF NOT EXISTS public.mobile_telemetry_conflicts (
  client_id uuid PRIMARY KEY,
  driver_id integer NOT NULL REFERENCES public.users(id),
  trip_id integer NOT NULL REFERENCES public.entregas(id),
  reason text NOT NULL CHECK (reason IN ('outside_trip','trip_not_started','payload_conflict')),
  payload jsonb NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.mobile_telemetry_conflicts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.mobile_telemetry_conflicts FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON public.mobile_telemetry_conflicts TO service_role;

CREATE OR REPLACE FUNCTION public.koda_mobile_alerts(p_driver integer, p_trip integer)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.aberto_at DESC), '[]'::jsonb)
 FROM jsonb_array_elements(koda_mobile_trips(p_driver,p_trip)) t
 JOIN carga_alertas a ON a.id_carga=coalesce((t->>'carga_id_mobile')::integer,(t->'caminhao'->>'id_carga')::integer)
 WHERE (t->>'data_saida') IS NOT NULL
 AND a.aberto_at <= coalesce((t->>'data_entrega')::timestamp,CASE WHEN t->>'status'='cancelada' THEN (t->>'updated_at')::timestamp END,timezone('utc',now()))
 AND coalesce(a.resolvido_at,CASE WHEN a.status='aberto' THEN 'infinity'::timestamp ELSE a.updated_at END) >= (t->>'data_saida')::timestamp;
$$;
REVOKE ALL ON FUNCTION public.koda_mobile_alerts(integer,integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.koda_mobile_alerts(integer,integer) TO service_role;

CREATE OR REPLACE FUNCTION public.koda_mobile_telemetry(p_driver integer,p_readings jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE r jsonb; e public.entregas; t public.caminhao; cargo_id integer;
 accepted jsonb:='[]'; rejected jsonb:='[]'; stamp timestamp; reason text;
 existing public.carga_telemetria_auditoria; conflict public.mobile_telemetry_conflicts;
BEGIN
 PERFORM 1 FROM users WHERE id=p_driver AND role='driver' AND is_active FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Motorista sem acesso' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(p_readings)<>'array' OR jsonb_array_length(p_readings) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Lote inválido' USING ERRCODE='22023'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_readings) ORDER BY (value->>'tripId')::integer,(value->>'timestamp')::timestamptz LOOP
   SELECT t0.* INTO t FROM caminhao t0 JOIN entregas e0 ON e0.id_caminhao=t0.id WHERE e0.id=(r->>'tripId')::integer FOR UPDATE OF t0;
   SELECT * INTO e FROM entregas WHERE id=(r->>'tripId')::integer FOR UPDATE;
   IF e.id IS NULL OR coalesce(e.motorista_id_mobile,t.id_usuario) IS DISTINCT FROM p_driver THEN RAISE EXCEPTION 'Viagem indisponível' USING ERRCODE='42501'; END IF;
   stamp:=timezone('utc',(r->>'timestamp')::timestamptz);
   IF (r->>'id') IS NULL OR stamp IS NULL OR stamp>timezone('utc',now())+interval '1 minute'
      OR (r->>'temperature') IS NULL OR (r->>'temperature')::numeric NOT BETWEEN -100 AND 100
      OR ((r->>'latitude') IS NOT NULL AND (r->>'latitude')::numeric NOT BETWEEN -90 AND 90)
      OR ((r->>'longitude') IS NOT NULL AND (r->>'longitude')::numeric NOT BETWEEN -180 AND 180)
   THEN RAISE EXCEPTION 'Leitura inválida' USING ERRCODE='22023'; END IF;
   SELECT * INTO conflict FROM mobile_telemetry_conflicts WHERE client_id=(r->>'id')::uuid;
   IF conflict.client_id IS NOT NULL THEN
     IF conflict.driver_id<>p_driver OR conflict.trip_id<>e.id OR conflict.payload<>r THEN RAISE EXCEPTION 'Identificador reutilizado com dados diferentes' USING ERRCODE='22023'; END IF;
     rejected:=rejected||jsonb_build_array(jsonb_build_object('id',r->>'id','reason',conflict.reason));CONTINUE;
   END IF;
   reason:=NULL;
   SELECT * INTO existing FROM carga_telemetria_auditoria WHERE client_id_mobile=(r->>'id')::uuid;
   IF existing.id IS NOT NULL THEN
     IF existing.id_entrega_mobile IS DISTINCT FROM e.id OR existing.temperatura IS DISTINCT FROM round((r->>'temperature')::numeric,2)
       OR existing.created_at IS DISTINCT FROM stamp OR existing.latitude IS DISTINCT FROM round((r->>'latitude')::numeric,6)
       OR existing.longitude IS DISTINCT FROM round((r->>'longitude')::numeric,6)
     THEN RAISE EXCEPTION 'Identificador reutilizado com dados diferentes' USING ERRCODE='22023'; END IF;
     accepted:=accepted||jsonb_build_array(r->>'id');CONTINUE;
   END IF;
   IF e.data_saida IS NULL OR e.status='pendente' THEN reason:='trip_not_started';
   ELSIF stamp<e.data_saida-interval '1 minute'
     OR (e.data_entrega IS NOT NULL AND stamp>e.data_entrega)
     OR (e.status='cancelada' AND stamp>e.updated_at)
     OR (e.status='entregue' AND e.data_entrega IS NULL)
   THEN reason:='outside_trip'; END IF;
   IF reason IS NOT NULL THEN
     INSERT INTO mobile_telemetry_conflicts(client_id,driver_id,trip_id,reason,payload) VALUES((r->>'id')::uuid,p_driver,e.id,reason,r);
     rejected:=rejected||jsonb_build_array(jsonb_build_object('id',r->>'id','reason',reason));CONTINUE;
   END IF;
   cargo_id:=coalesce(e.carga_id_mobile,t.id_carga);
   IF cargo_id IS NULL THEN RAISE EXCEPTION 'Carga não informada' USING ERRCODE='P0001'; END IF;
   PERFORM 1 FROM carga WHERE id=cargo_id FOR UPDATE;
   INSERT INTO carga_telemetria_auditoria(id_carga,id_entrega_mobile,client_id_mobile,temperatura,latitude,longitude,created_at)
   VALUES(cargo_id,e.id,(r->>'id')::uuid,(r->>'temperature')::numeric,(r->>'latitude')::numeric,(r->>'longitude')::numeric,stamp);
   -- Completed trips receive their late audit rows, without moving a reused cargo.
   IF e.status IN ('em_transito','no_armazem') AND NOT EXISTS(SELECT 1 FROM carga_telemetria_auditoria WHERE id_carga=cargo_id AND created_at>stamp) THEN
     UPDATE carga SET temperatura_atual=(r->>'temperature')::numeric,latitude=coalesce((r->>'latitude')::numeric,latitude),longitude=coalesce((r->>'longitude')::numeric,longitude),updated_at=timezone('utc',now()) WHERE id=cargo_id;
   END IF;
   accepted:=accepted||jsonb_build_array(r->>'id');
 END LOOP;
 RETURN jsonb_build_object('acceptedIds',accepted,'rejected',rejected);
END;
$$;
REVOKE ALL ON FUNCTION public.koda_mobile_telemetry(integer,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.koda_mobile_telemetry(integer,jsonb) TO service_role;


-- 005_closed_trip_alerts.sql
-- Prevent late completed-trip readings from changing the current cargo alert. Run after 004.

CREATE OR REPLACE FUNCTION public.koda_mobile_schema_version()
RETURNS integer LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT 5; $$;
REVOKE ALL ON FUNCTION public.koda_mobile_schema_version() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.koda_mobile_schema_version() TO service_role;
CREATE OR REPLACE FUNCTION fn_carga_telemetria_processar_alertas()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_min       DECIMAL(5,2);
    v_max       DECIMAL(5,2);
    v_tipo      TEXT;
    v_alerta_id INT;
BEGIN
    IF NEW.id_entrega_mobile IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.entregas WHERE id=NEW.id_entrega_mobile AND status IN ('entregue','cancelada')
    ) THEN RETURN NEW; END IF;
    -- Offline packets remain in the audit trail. They must not reverse a newer
    -- thermal state already observed by the web central or another device.
    IF EXISTS (SELECT 1 FROM public.carga_telemetria_auditoria
        WHERE id_carga = NEW.id_carga AND
        (created_at > NEW.created_at OR (created_at = NEW.created_at AND id > NEW.id))) THEN
        RETURN NEW;
    END IF;
    -- Lê faixa atual da carga referenciada
    SELECT temperatura_minima, temperatura_maxima
      INTO v_min, v_max
      FROM carga
     WHERE id = NEW.id_carga;

    -- Se a carga não existe ou não tem faixa, não há o que avaliar
    IF v_min IS NULL OR v_max IS NULL THEN
        RETURN NEW;
    END IF;

    -- Classifica a leitura
    IF NEW.temperatura > v_max THEN
        v_tipo := 'alta';
    ELSIF NEW.temperatura < v_min THEN
        v_tipo := 'baixa';
    ELSE
        v_tipo := NULL;  -- dentro da faixa
    END IF;

    ----------------------------------------------------------------
    -- CASO A: leitura DENTRO da faixa
    --   Fecha qualquer alerta aberto da carga (independente do tipo).
    ----------------------------------------------------------------
    IF v_tipo IS NULL THEN
        UPDATE carga_alertas
           SET status                  = 'resolvido',
               resolvido_at            = NEW.created_at,
               resolvido_telemetria_id = NEW.id,
               temperatura_fim         = NEW.temperatura,
               qtd_pings               = qtd_pings + 1,
               updated_at              = CURRENT_TIMESTAMP
         WHERE id_carga = NEW.id_carga
           AND status   = 'aberto';

        RETURN NEW;
    END IF;

    ----------------------------------------------------------------
    -- CASO B: leitura FORA da faixa
    --   B.1) Existe alerta aberto do MESMO tipo  → só atualiza
    --   B.2) Existe alerta aberto do TIPO OPOSTO → fecha o oposto e
    --        abre o novo (cruzou de baixa para alta ou vice-versa)
    --   B.3) Não existe alerta aberto            → abre novo
    --
    -- Lock pessimista (FOR UPDATE) garante que dois inserts
    -- concorrentes não criem 2 alertas iguais (o índice unique parcial
    -- também blinda isso, mas o lock evita o erro 23505).
    ----------------------------------------------------------------
    SELECT id INTO v_alerta_id
      FROM carga_alertas
     WHERE id_carga = NEW.id_carga
       AND tipo     = v_tipo
       AND status   = 'aberto'
     FOR UPDATE;

    IF FOUND THEN
        -- B.1 — só atualiza pico e contagem
        UPDATE carga_alertas
           SET temperatura_pico = CASE
                   WHEN tipo = 'alta' THEN GREATEST(temperatura_pico, NEW.temperatura)
                   ELSE                   LEAST   (temperatura_pico, NEW.temperatura)
               END,
               qtd_pings  = qtd_pings + 1,
               updated_at = CURRENT_TIMESTAMP
         WHERE id = v_alerta_id;
    ELSE
        -- B.2 — fecha alerta do tipo OPOSTO se houver
        UPDATE carga_alertas
           SET status                  = 'resolvido',
               resolvido_at            = NEW.created_at,
               resolvido_telemetria_id = NEW.id,
               temperatura_fim         = NEW.temperatura,
               qtd_pings               = qtd_pings + 1,
               updated_at              = CURRENT_TIMESTAMP
         WHERE id_carga = NEW.id_carga
           AND tipo    <> v_tipo
           AND status   = 'aberto';

        -- B.3 — abre novo
        INSERT INTO carga_alertas (
            id_carga, tipo, status,
            limite_minimo, limite_maximo,
            temperatura_inicio, temperatura_pico,
            aberto_telemetria_id,
            aberto_at, qtd_pings
        ) VALUES (
            NEW.id_carga, v_tipo, 'aberto',
            v_min, v_max,
            NEW.temperatura, NEW.temperatura,
            NEW.id,
            NEW.created_at, 1
        );
    END IF;

    RETURN NEW;
END;
$$;




